// script.min.js - minified by Copilot
let current=0;const colors=["red","yellow","green"];function updateSemaforoIcon(){document.querySelectorAll('.semaforo-icon .light').forEach((el,i)=>{el.classList.toggle('active',i===current)});let delay=current===0?3500:current===1?900:2300;current=(current+1)%colors.length;setTimeout(updateSemaforoIcon,delay)}if(document.querySelector('.semaforo-icon'))updateSemaforoIcon();document.querySelectorAll('.faq-item').forEach(item=>{item.addEventListener('click',function(){document.querySelectorAll('.faq-item').forEach(i=>i.classList.remove('open'));this.classList.add('open')})});const contactForm=document.getElementById('contact-form');if(contactForm){contactForm.addEventListener('submit',function(e){document.getElementById('form-status')&&(document.getElementById('form-status').textContent="A enviar..." )})}const orcamentoForm=document.getElementById('orcamento-form');if(orcamentoForm){orcamentoForm.addEventListener('submit',function(e){e.preventDefault();document.getElementById('orcamento-status')&&(document.getElementById('orcamento-status').textContent="A enviar...")})}const anoFooter=document.getElementById('anoFooter');if(anoFooter)anoFooter.textContent=new Date().getFullYear();document.querySelectorAll(".parceiro-card").forEach(card=>{card.addEventListener("click",function(){const url=this.getAttribute("data-url");this.style.transform="scale(0.95)";setTimeout(()=>{this.style.transform="";window.open(url,"_blank")},200)})});const fadeSection=document.querySelector(".fade-section");function revealOnScroll(){if(!fadeSection)return;const sectionTop=fadeSection.getBoundingClientRect().top;const windowHeight=window.innerHeight;if(sectionTop<windowHeight-100)fadeSection.classList.add("visible")}window.addEventListener("scroll",revealOnScroll);window.addEventListener("load",revealOnScroll);
